_⚠️ Potential issue_ | _🟠 Major_

**Ensure workflow polling is always cleaned up and network errors are handled.**

The interval is not cleared on unmount/close and poll request failures are unhandled. This can leak timers and leave UI in an invalid state.


<details>
<summary>💡 Proposed fix</summary>

```diff
 const InstallModal = ({ app, onClose }: { app: AppInfo; onClose: () => void }) => {
+  const pollRef = React.useRef<ReturnType<typeof setInterval> | null>(null);
+
+  useEffect(() => {
+    return () => {
+      if (pollRef.current) clearInterval(pollRef.current);
+    };
+  }, []);
@@
-      const interval = setInterval(async () => {
-        const statusRes = await axios.get(`${API_BASE}/workflow/${workflowId}`);
-        setInstallStatus(statusRes.data);
-        if (statusRes.data.status === 'complete') {
-          clearInterval(interval);
-          setStep('complete');
-        } else if (statusRes.data.status === 'failed') {
-          clearInterval(interval);
-          setError(statusRes.data.error || "Installation failed");
-          setStep('error');
-        }
-      }, 2000);
+      pollRef.current = setInterval(async () => {
+        try {
+          const statusRes = await axios.get(`${API_BASE}/workflow/${workflowId}`);
+          setInstallStatus(statusRes.data);
+          if (statusRes.data.status === 'complete') {
+            if (pollRef.current) clearInterval(pollRef.current);
+            setStep('complete');
+          } else if (statusRes.data.status === 'failed') {
+            if (pollRef.current) clearInterval(pollRef.current);
+            setError(statusRes.data.error || "Installation failed");
+            setStep('error');
+          }
+        } catch (e: any) {
+          if (pollRef.current) clearInterval(pollRef.current);
+          setError(e?.message || "Workflow status check failed");
+          setStep('error');
+        }
+      }, 2000);
```
</details>

